"""Boilerplate files are generated by cobo (github.com/hasansezertasan/cobo)."""

import shutil
import tomllib

import pytest

from conftest import run

MANAGED = {".gitignore", ".gitattributes", ".editorconfig"}


@pytest.fixture
def rendered(render):
    result, dest = render()
    assert result.returncode == 0, result.stderr
    return dest


def test_lockfile_tracks_exactly_the_managed_files(rendered):
    lock = tomllib.loads((rendered / "cobo.lock").read_text())
    assert {f["path"] for f in lock["fragment"]} == MANAGED


def test_managed_files_carry_a_sealed_fence(rendered):
    for name in MANAGED:
        text = (rendered / name).read_text()
        assert "# >>> cobo:begin >>>" in text, name
        assert "# <<< cobo:end sha256=" in text, name


def test_rendered_seals_are_intact(rendered):
    assert shutil.which("cobo"), "cobo must be on PATH (mise installs it)"
    # Run from a neutral cwd: mise shims would otherwise parse the rendered
    # repo's untrusted .config/mise.toml before cobo starts.
    result = run("cobo", "check", "--lock-file", str(rendered / "cobo.lock"), cwd=rendered.parent)
    assert result.returncode == 0, result.stdout + result.stderr
    assert "0 fragment(s) need updating" in result.stdout


def test_copy_tells_the_author_cobo_owns_the_boilerplate(render):
    result, _ = render()
    assert result.returncode == 0, result.stderr
    assert "cobo gitignore dump" in result.stderr


def test_cobo_is_pinned_in_mise_and_checked_weekly(rendered):
    mise = tomllib.loads((rendered / ".config" / "mise.toml").read_text())
    assert mise["tools"]["pipx:cobo"] == "0.6.0"
    assert (rendered / ".github" / "workflows" / "cobo-drift.yml").is_file()
